CREATE TABLE payment_gateway_configs(id BINARY(16) PRIMARY KEY,tenant_id BINARY(16) NOT NULL,provider VARCHAR(40) NOT NULL,enabled BOOLEAN NOT NULL,public_key VARCHAR(255),secret_key VARCHAR(500),upi_vpa VARCHAR(120),payee_name VARCHAR(120),updated_at TIMESTAMP(6) NOT NULL,UNIQUE KEY uk_gateway_tenant_provider(tenant_id,provider));
CREATE TABLE wallets(id BINARY(16) PRIMARY KEY,tenant_id BINARY(16) NOT NULL,user_id BINARY(16) NOT NULL,balance DECIMAL(14,2) NOT NULL,currency VARCHAR(3) NOT NULL,status VARCHAR(20) NOT NULL,updated_at TIMESTAMP(6) NOT NULL,UNIQUE KEY uk_wallet_tenant_user(tenant_id,user_id));
CREATE TABLE wallet_entries(id BINARY(16) PRIMARY KEY,wallet_id BINARY(16) NOT NULL,amount DECIMAL(14,2) NOT NULL,balance_after DECIMAL(14,2) NOT NULL,reason VARCHAR(50) NOT NULL,reference VARCHAR(120),created_at TIMESTAMP(6) NOT NULL,CONSTRAINT fk_wallet_entry_wallet FOREIGN KEY(wallet_id)REFERENCES wallets(id),INDEX idx_wallet_entries(wallet_id,created_at));
CREATE TABLE scan_pay_orders(id BINARY(16) PRIMARY KEY,order_number VARCHAR(40) NOT NULL UNIQUE,tenant_id BINARY(16) NOT NULL,user_id BINARY(16) NOT NULL,station_id BINARY(16),charger_id BINARY(16),amount DECIMAL(12,2) NOT NULL,currency VARCHAR(3) NOT NULL,status VARCHAR(20) NOT NULL,payment_id BINARY(16),session_id BINARY(16),payload VARCHAR(1000) NOT NULL,created_at TIMESTAMP(6) NOT NULL,updated_at TIMESTAMP(6) NOT NULL,INDEX idx_scan_pay_tenant(tenant_id,created_at));
